sys_script.script:
(function executeRule(current, previous /*null when async*/) {

			var grt = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
			var assignment = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs');
			grt.addQuery('parent',current.sys_id);
			grt.addQuery('state','IN','1,2');
			grt.addQuery('task_type','Manually Process Email');
			grt.query();
			if(!grt.hasNext()){
				var grn = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
				grn.initialize();
				grn.task_type="Manually Process Email";
				grn.short_description="Error while trying to Process Data in SWB: "+ current.swb_status;
				grn.parent=current.sys_id;
				grn.qtrack_id=current.qtrack_id;
				grn.swb_id=current.swb_id;
				grn.assignment_group = assignment;
				grn.state='1';
				grn.entity = current.entity;
				grn.insert();
			}

})(current, previous);
